        response = requests.get(url, verify=verify_cert)
        response.raise_for_status()
    except requests.ConnectionError as e:
        raise ConnectionError(f"Could not connect to GitHub API: {e}")
    except requests.HTTPError as e:
        raise requests.HTTPError(f"HTTP error occurred while fetching repositories: {e}")
    try:
        repos = response.json()
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to parse JSON response: {e}")
    if not isinstance(repos, list):
        raise ValueError("Unexpected response format from GitHub API.")
    RepoInfo = collections.namedtuple('RepoInfo', ['name', 'created_at'])
    repo_infos = []
    for repo in repos:
        name = repo.get('name')
        created_at = repo.get('created_at')
        if name is None or created_at is None:
            continue
        repo_infos.append(RepoInfo(name=name, created_at=created_at))
    repo_infos.sort(key=lambda r: r.created_at)
    return [r.name for r in repo_infos]

